templates.generator:
def generate(rng):
    item = rng.choice(['Latte', 'Flat white', 'Tea', 'Scone', 'Muffin', 'Toastie', 'Mocha', 'Brownie'])
    pence = rng.randint(150, 450)
    price = f'{pence // 100}.{pence % 100:02d}'
    return {'line1': f'Order: {item}', 'line2': f'Price: £{price}'}

def generate(rng):
    drink = rng.choice(['tea', 'latte', 'cocoa', 'mocha', 'espresso', 'cappuccino'])
    return {'table': rng.randint(1, 30), 'drink': drink, 'enjoy': 'Enjoy your ' + drink}
